			fail("Did not throw IllegalStateException");
		} catch (Exception e) {
			if (!(e instanceof IllegalStateException)) {
				fail("Did not throw IllegalStateException");
			}
		}
		try {
			b.remove(7);
			iter.next();
			fail("Did not throw ConcurrentModificationException");
