		assertEquals(3, b.size());

		BinarySearchTree.Node n4 = b.new Node(4);
		n1.setLeft(n4);
		assertEquals(4, b.size());

		BinarySearchTree.Node n5 = b.new Node(5);
		n4.setLeft(n5);
		assertEquals(5, b.size());

		BinarySearchTree.Node n6 = b.new Node(6);
		n5.setRight(n6);
		assertEquals(6, b.size());
	}

