	@Test
	public void testRemoveInPreOrderIterator() {
		BinarySearchTree<Integer> b = new BinarySearchTree<Integer>();

		// Testing exception throwing on empty tree.
		Iterator<Integer> iter = b.preOrderIterator();
		try {
