		b.remove(10);
		a[0] = 4;
		a[1] = 14;
		iter = b.preOrderIterator();
		assertTrue(iter.hasNext(), "Expected: true");
		for (int k = 0; k < a.length; k++) {
			assertEquals(a[k], iter.next());
		}
		points += 3;
	}


