		assertEquals("[1, 2, 3, 15]", b.toString());
		Integer[] p = { 3, 2, 1, 15 };
		boolean boo3[] = { true, true, true, false };
		iter = b.preOrderIterator();
		assertTrue(iter.hasNext());
		for (int k = 0; k < p.length; k++) {
