			 		stack.push(left);
			 		flags.push(1);
			 		prev = left;
			 		left = left.left;
			 	}
				return prev.data;
			}
		 	Node right = cur.right; // 2 means this part
		 	if (right != NULL_NODE) {
		 		stack.push(right);
		 		flags.push(1);
		 		return cur.data;
	 		}
		 	return null;
		}

	}
}

