			}
		}

		b.insert(5);
		b.insert(3);
		b.insert(7);
		iter = b.iterator();

		// Testing exception throwing when next() has not been
		// called yet.
		assertTrue(iter.hasNext());
		try {
			iter.remove();
			fail("Did not throw IllegalStateException");
		} catch (Exception e) {
			if (!(e instanceof IllegalStateException)) {
				fail("Did not throw IllegalStateException");
			}
		}

		iter.next();
		assertTrue(iter.hasNext());
		iter.next();
		iter.remove();
		assertEquals("[3, 7]", b.toString());

		try {
			iter.remove();
			fail("Did not throw IllegalStateException");
		} catch (Exception e) {
