	private Node removeHelper(Node cur, T i, boolean[] b) {
		if (cur == NULL_NODE) {
			return NULL_NODE;
		}
		int comparison = i.compareTo(cur.data);
		if (comparison == 0) {
			b[0] = true;
			// Three cases:
			if (cur.left != NULL_NODE && cur.right != NULL_NODE) { // cur has 2 children
				Node prev = cur;
				Node bottom = cur.left;
				int comp2 = bottom.data.compareTo(cur.right.data);
				while (bottom.right != NULL_NODE && comp2 < 0) { // keep going right while exploring a viable candidate
					prev = bottom;
					bottom = bottom.right;
					comp2 = bottom.data.compareTo(cur.right.data);
				}
				if (bottom != cur.left) { // we're down there
					// Bottom is guaranteed greater than the left and less than the right

					//extricate
					prev.right = removeHelper(bottom,bottom.data,b);
					// using it as root
					bottom.right = cur.right;
					bottom.left = cur.left;
					return bottom; // new root
				} else { // the left's right is null; since it's all lefts, just shift up
					bottom.right = cur.right;
					return bottom;
				}
			} else if (cur.left != NULL_NODE) { // 1 child
				return cur.left;
			} else if (cur.right != NULL_NODE) { // 1 child
				return cur.right;
			} else { // no children
				return NULL_NODE;
			}
		} else if (comparison < 0) { // i < cur.data
			// it belongs left
			Node newLeft = removeHelper(cur.left, i, b);
			cur.left = newLeft;
		} else { // i > cur.data
			Node newRight = removeHelper(cur.right, i, b);
			cur.right = newRight;
		}
		return cur;
	}
